svg.script:
console.log(">> IIoT CELL LOADED:", webMI.query["base"]);
var base = webMI.query["base"];

// Simple reads
webMI.data.read(base + ".punto", function (e) {
    webMI.gfx.setText("id_1", e.value);
});

webMI.data.read(base + ".ID_corto", function (e) {
    webMI.gfx.setText("id_13", e.value);
});

// Consolidated reads for connectivity and display data
webMI.data.read(base + ".connectivity", function (e) {
    var status = e.status;
    var value = e.value;
    var timestamp = e.timestamp;
    var now = new Date();

    // 1. Connectivity Indicator (id_10)
    webMI.gfx.setFill("id_10", value ? "#fafafa" : "#a3a3a3");

    // 2. OPC UA Status LED (id_5)
    var statusColors = {
        0: "#1a8b22",          // Good (Normal)
        10878976: "blue",      // GoodMoreData (Sincronización)
        2150694912: "#ff0000", // BadNoCommunication (No Com.)
        2150760448: "#7c1536", // BadWaitingForInitialData (Iniciando)
        2156593152: "#b98f2d", // BadDeviceFailure (Falla Equipo)
        2156658688: "#e64980", // BadSensorFailure (Falla Sensor)
        2158821376: "orange",  // BadDisconnect (Desconectado)
        2147483648: "#ff8f05", // Bad (Falla Gral.)
        2156724224: "#495057", // BadOutOfService (Fuera Serv.)
        1083179008: "#883fb2", // UncertainLastUsableValue (Incierto)
        2148335616: "#555555"  // BadServerNotConnected
    };
    webMI.gfx.setFill("id_5", statusColors[status] || "#000000");

    // 3. Timestamp & Recency Indicator (id_4 background, id_6 text)
    const date = new Date(timestamp);
    const options = { year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' };
    const formattedDate = new Intl.DateTimeFormat('es-MX', options).format(date);
    webMI.gfx.setText("id_6", formattedDate.toString());

    var diffDays = (now - date) / (1000 * 60 * 60 * 24);
    var isToday = date.toDateString() === now.toDateString();
    var isThisMonth = date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();

    var recencyColor = "#ff0000";
    if (isToday) recencyColor = "#1a8b22";
    else if (diffDays <= 7) recencyColor = "#1c7ed6";
    else if (isThisMonth) recencyColor = "#f59f00";

    webMI.gfx.setFill("id_4", recencyColor);
    webMI.gfx.setFill("id_13", "#ffffff");
    webMI.gfx.setFill("id_6", "#ffffff");
});
